function Get-UpcatReadingComprehensionBank {
  return @(
    @{ q = 'Passage: A town library moved several study tables beside large windows. Within a month, afternoon attendance increased and students stayed longer. Which statement best expresses the main idea of the passage?'; c = 'A simple layout change made the library more appealing for studying.'; d = @('Libraries should remove all indoor lights.', 'Students dislike quiet places in the afternoon.', 'Window seats are useful only for decoration.'); e = 'The passage centers on how moving tables near natural light improved study use of the library.' },
    @{ q = 'Passage: During a drought, a school began collecting rainwater from roof gutters and storing it in tanks for garden use. As a result, the vegetable plots survived the dry months. What can be inferred from the passage?'; c = 'The stored rainwater helped reduce the need for fresh tap water.'; d = @('The school stopped growing vegetables permanently.', 'Rainwater damaged the plants more than drought did.', 'The tanks were used mainly for classroom cleaning.'); e = 'Because rainwater was stored and used for the garden during drought, it likely reduced dependence on tap water.' },
    @{ q = 'Passage: A student group proposed bike racks near the campus gate. After the racks were installed, more students began cycling to school and congestion near the entrance lessened slightly. What is the author purpose of the passage?'; c = 'To show how a small facility change affected student travel behavior'; d = @('To criticize students who still walk to school', 'To explain how bicycles are manufactured', 'To compare bike racks with bus terminals'); e = 'The passage mainly explains the effect of the bike racks on transport habits and congestion.' },
    @{ q = 'Passage: The editor removed several dramatic adjectives from the article before publication. She explained that the report needed evidence, not exaggeration. Which word best describes the editor tone?'; c = 'objective'; d = @('playful', 'angry', 'uncertain'); e = 'The editor emphasizes evidence and restraint, which suggests an objective tone.' },
    @{ q = 'Passage: When the science fair switched from printed posters to reusable boards, setup time became shorter and less paper was thrown away after the event. Which conclusion is best supported?'; c = 'Reusable boards made the science fair more efficient and less wasteful.'; d = @('Printed posters are always more creative than boards.', 'Students refused to join the fair after the change.', 'The fair became longer because of the new boards.'); e = 'The passage directly links reusable boards with faster setup and less waste.' },
    @{ q = 'Passage: Sa isang barangay, naglagay ng libreng palamigan ng inumin sa waiting shed tuwing tag-init. Maraming drayber at pasahero ang nagsabing mas naging maginhawa ang paghihintay. Ano ang pangunahing ideya ng talata?'; c = 'Nakatulong ang simpleng proyekto upang maging mas maginhawa ang paghihintay ng mga tao.'; d = @('Lahat ng waiting shed ay may palamigan na.', 'Ayaw ng mga drayber sa libreng inumin.', 'Mas mainam ang maghintay sa bahay kaysa sa shed.'); e = 'Ipinapakita ng talata na ang simpleng proyekto ay nakapagbigay ng ginhawa sa mga naghihintay.' },
    @{ q = 'Passage: The debate team reviewed weak arguments first, even though members preferred practicing their strongest speeches. Their coach said improvement happens fastest where mistakes are most common. What idea does the coach emphasize?'; c = 'Students improve more when they work directly on weaknesses.'; d = @('Strong speeches should never be practiced again.', 'Mistakes should be ignored during preparation.', 'Debate is less important than confidence.'); e = 'The coach prioritizes correcting common mistakes because that is where improvement is greatest.' },
    @{ q = 'Passage: A farmer planted two rice varieties in nearby plots. One variety produced more grain, but the other survived flooding better. Why might the farmer still keep the second variety?'; c = 'It may be more reliable during seasons with heavy rain.'; d = @('It always grows faster in every condition.', 'It requires no soil at all.', 'It can replace all farm tools.'); e = 'Even if it yields less, the flood-tolerant variety may be valuable in risky weather conditions.' },
    @{ q = 'Passage: The museum guide paused longer at the final painting and asked visitors to compare its colors with those in the first room. This suggests that the guide wanted visitors to'; c = 'notice a contrast across the exhibit'; d = @('leave the museum immediately', 'memorize the artist birthdays', 'ignore the first room entirely'); e = 'By asking for comparison, the guide is directing attention to contrast between the works.' },
    @{ q = 'Passage: The article explains that mangrove roots trap sediment, reduce erosion, and provide shelter for young fish. Which title best fits the passage?'; c = 'Why Mangroves Matter in Coastal Areas'; d = @('How to Build a Fishing Boat', 'The Most Expensive Trees in the World', 'Why Sand Always Disappears'); e = 'The passage focuses on the ecological value of mangroves in coastal environments.' },
    @{ q = 'Passage: Isinulat ng may-akda na "unti-unting kumapal ang katahimikan sa silid habang binabasa ang resulta." Ano ang ipinahihiwatig ng linyang ito?'; c = 'Lalong tumindi ang kaba ng mga tao habang hinihintay ang kinalabasan.'; d = @('Naging mas maingay ang silid habang nagbabasa.', 'Walang sinuman ang interesado sa resulta.', 'Tapos na agad ang pagpupulong bago pa magbasa.'); e = 'Ang lumalalim na katahimikan ay palatandaan ng matinding tensiyon o kaba.' },
    @{ q = 'Passage: A principal introduced a ten-minute reading period before the first class each day. After several weeks, teachers noticed that students settled more quickly and late arrivals decreased. What is the best conclusion?'; c = 'The reading period may have improved the start-of-day routine.'; d = @('Students now dislike reading more than before.', 'Teachers stopped teaching after first period.', 'Late arrivals increased because of longer classes.'); e = 'The observed changes suggest the reading period had a positive effect on morning routines.' },
    @{ q = 'Passage: The report states that a river cleanup removed visible trash, but water tests still showed high bacteria levels. What does this indicate?'; c = 'Solving the river problem requires more than removing visible waste.'; d = @('The cleanup was completely useless in every way.', 'Bacteria can be seen easily without testing.', 'Trash is the only source of water pollution.'); e = 'Visible trash removal helped appearance, but the test results show deeper water-quality problems remain.' },
    @{ q = 'Passage: The poet describes the streetlights as "tired stars above the empty road." What does this figurative language mainly do?'; c = 'It creates an image of dim light and loneliness.'; d = @('It proves the road is actually in space.', 'It explains how electricity is generated.', 'It shows the speaker is studying astronomy.'); e = 'Comparing the streetlights to tired stars creates a mood of faint light and solitude.' },
    @{ q = 'Passage: A canteen replaced plastic spoons with metal ones that students returned after meals. At first, staff worried about delays, but after one month the serving line moved at the same speed as before. Which concern was not supported by the result?'; c = 'That reusable spoons would slow service significantly'; d = @('That metal spoons would need cleaning', 'That students would continue eating at lunch', 'That staff would need to organize returns'); e = 'The passage says line speed stayed the same, so major delay was not supported.' },
    @{ q = 'Passage: Sa ulat, sinabi na mas mataas ang ani ng mga magsasakang gumamit ng organikong pataba sa loob ng dalawang taniman. Gayunman, wala pang sapat na datos para sabihing ito ang pinakamabisang paraan sa lahat ng lugar. Ano ang pinakamainam na konklusyon?'; c = 'May positibong palatandaan, ngunit kailangan pa ng mas malawak na pag-aaral.'; d = @('Patunay na organiko ang pinakamahusay sa lahat ng sitwasyon.', 'Walang epekto ang organikong pataba sa ani.', 'Dapat itigil agad ang paggamit ng ibang pataba.'); e = 'Ipinapakita ng ulat ang maingat na konklusyon: may magandang resulta, pero kulang pa ang ebidensiya para sa pangkalahatang pahayag.' },
    @{ q = 'Passage: The mayor speech promised "lasting reform," but the article notes that similar promises were made in the past with little follow-through. How does the article mainly treat the promise?'; c = 'with skepticism'; d = @('with complete trust', 'with celebration only', 'with total indifference'); e = 'By recalling earlier promises that were not fulfilled, the article treats the new promise skeptically.' },
    @{ q = 'Passage: Students were asked to survey neighbors about waste segregation. Many respondents knew the rules, but fewer actually followed them consistently. What is the strongest inference?'; c = 'Awareness alone does not guarantee proper practice.'; d = @('Most respondents had never heard of waste segregation.', 'The survey questions were impossible to answer.', 'Neighbors wanted stricter school uniforms.'); e = 'The contrast between knowing the rules and following them shows that awareness does not automatically lead to action.' },
    @{ q = 'Passage: The passage compares two study methods: highlighting notes and answering practice questions. It reports that students remembered more when they had to retrieve answers from memory. Which method does the passage favor?'; c = 'answering practice questions'; d = @('highlighting alone', 'copying notes by hand only', 'avoiding all review activities'); e = 'The passage says memory was stronger when students actively retrieved answers through practice questions.' },
    @{ q = 'Passage: In the story, Lito kept repairing the old radio even after others said it was useless. At the end, it worked again. Which trait is most clearly shown by Lito?'; c = 'persistence'; d = @('envy', 'carelessness', 'dishonesty'); e = 'Lito continues working despite discouragement, which shows persistence.' },
    @{ q = 'Passage: The school paper published student essays in both English and Filipino to reach more readers. What was the likely reason for this choice?'; c = 'Different readers are more comfortable with different languages.'; d = @('One language is always incorrect for school writing.', 'The essays were too short to publish in one language.', 'Students were forbidden to read bilingual texts.'); e = 'Publishing in both languages likely helps the paper communicate with a wider range of readers.' },
    @{ q = 'Passage: Ipinaliwanag sa talata na kahit mataas ang marka ng isang paaralan sa pagsusulit, mahalaga pa ring tingnan kung pantay ang pag-unlad ng lahat ng mag-aaral. Ano ang binibigyang-diin ng may-akda?'; c = 'Hindi sapat ang pangkalahatang marka kung may mga naiiwang mag-aaral.'; d = @('Dapat itigil ang lahat ng pagsusulit sa paaralan.', 'Mas mahalaga ang isang mag-aaral kaysa sa buong paaralan.', 'Pare-pareho ang bilis ng pag-unlad ng lahat ng bata.'); e = 'Binibigyang-diin ng may-akda ang kahalagahan ng patas at malawakang pag-unlad, hindi lamang mataas na average.' },
    @{ q = 'Passage: A town built a covered walkway between two school buildings. Teachers reported fewer late arrivals during rainy days, but little change on dry days. What does this suggest?'; c = 'The walkway mainly helped when weather made movement difficult.'; d = @('The walkway increased lateness in all seasons.', 'Rain has no effect on student movement.', 'Students avoided the buildings after the walkway was built.'); e = 'Because the improvement appeared mainly on rainy days, the walkway seems most useful in bad weather.' },
    @{ q = 'Passage: The article begins with a surprising statistic, then explains possible causes, and ends by proposing solutions. Which text structure is used most clearly?'; c = 'problem and solution'; d = @('chronological biography', 'pure comparison only', 'myth and legend'); e = 'The article presents an issue, examines causes, and ends with proposed solutions.' },
    @{ q = 'Passage: When the lights went out, the campers laughed at first, but soon their voices dropped as the forest sounds grew louder. What mood is created near the end?'; c = 'uneasy'; d = @('triumphant', 'cheerful', 'formal'); e = 'The quieter voices and louder forest sounds create an uneasy mood.' },
    @{ q = 'Passage: The reviewer writes that the new textbook is "ambitious, carefully organized, and occasionally too dense for beginners." Which statement best captures the reviewer overall judgment?'; c = 'The book is strong overall but may be difficult for some readers.'; d = @('The book has no strengths at all.', 'The book is useless for every learner.', 'The book is entertaining but unorganized.'); e = 'The reviewer gives praise but also includes a clear limitation, showing a balanced judgment.' },
    @{ q = 'Passage: In a field test, one water filter removed mud effectively but left an odor, while another improved taste but clogged quickly. What is the central idea?'; c = 'Each filter solved a different problem but had its own drawback.'; d = @('Both filters failed in every way.', 'The test proved water should never be filtered.', 'Odor is more important than safety in all cases.'); e = 'The passage compares two options, each with benefits and disadvantages.' },
    @{ q = 'Passage: "Hindi man agad nakita ang pagbabago, dahan-dahan naman itong naipon sa araw-araw na pagsisikap," wika ng coach. Ano ang pinakamalapit na kahulugan nito?'; c = 'May mga pagbabagong unti-unting lumalabas bunga ng tuloy-tuloy na pagsisikap.'; d = @('Walang silbi ang araw-araw na ensayo.', 'Mas mahalaga ang madaliang resulta kaysa tiyaga.', 'Hindi kailanman makikita ang anumang pagbabago.'); e = 'Ipinahihiwatig ng pahayag na ang tuloy-tuloy na pagsisikap ay nagbubunga ng unti-unting pag-unlad.' },
    @{ q = 'Passage: A history exhibit displayed old maps beside present-day satellite images. Visitors were invited to compare coastlines, roads, and settlement patterns. What skill are visitors mainly encouraged to use?'; c = 'comparison of information from two sources'; d = @('memorizing dates only', 'guessing without evidence', 'ignoring visual details'); e = 'The exhibit asks visitors to compare features across historical and modern representations.' },
    @{ q = 'Passage: The writer describes the volunteer clinic as "small in size but large in reach." What is the meaning of the statement?'; c = 'The clinic serves many people despite limited space.'; d = @('The clinic building is physically growing.', 'The clinic treats only tall patients.', 'The clinic is larger than every hospital.'); e = 'The phrase contrasts physical size with social impact, showing that the clinic helps many people despite being small.' }
  )
}
